ret_t validate_credentials_ldap(cherokee_validator_ldap_t *ldap, cherokee_connection_t *conn) {
    ret_t result = ret_error;
    LDAPMessage *search_result = NULL;
    char *search_filter = NULL;
    char *user_dn = NULL;

    if (ldap == NULL || conn == NULL) {
        return ret_error;
    }

    if (conn->username == NULL || conn->password == NULL) {
        return ret_not_found;
    }

    search_filter = create_search_filter(conn->username);
    if (search_filter == NULL) {
        return ret_error;
    }

    int ldap_result = ldap_search_s(ldap->ldap_handle, ldap->base_dn, LDAP_SCOPE_SUBTREE,
                                    search_filter, NULL, 0, &search_result);
    if (ldap_result != LDAP_SUCCESS) {
        free(search_filter);
        return ret_error;
    }

    int entries_count = ldap_count_entries(ldap->ldap_handle, search_result);
    if (entries_count != 1) {
        ldap_msgfree(search_result);
        free(search_filter);
        return (entries_count == 0) ? ret_not_found : ret_error;
    }

    LDAPMessage *entry = ldap_first_entry(ldap->ldap_handle, search_result);
    user_dn = ldap_get_dn(ldap->ldap_handle, entry);
    if (user_dn == NULL) {
        ldap_msgfree(search_result);
        free(search_filter);
        return ret_error;
    }

    struct berval cred = {0, (char *)conn->password};
    int auth_result = ldap_bind_s(ldap->ldap_handle, user_dn, &cred, LDAP_AUTH_SIMPLE);
    if (auth_result != LDAP_SUCCESS) {
        ldap_memfree(user_dn);
        ldap_msgfree(search_result);
        free(search_filter);
        return ret_error;
    }

    result = ret_ok;

    ldap_memfree(user_dn);
    ldap_msgfree(search_result);
    free(search_filter);
    ldap_unbind(ldap->ldap_handle);

    return result;
}

ret_t validate_user_credentials(cherokee_validator_ldap_t *ldap, cherokee_connection_t *conn) {
    ret_t result = ret_error;
    LDAPMessage *search_result = NULL;
    char *user_dn = NULL;

    if (!ldap || !conn || !conn->user || !conn->password) {
        return ret_error;
    }

    if (ldap_connect(ldap) != LDAP_SUCCESS) {
        return ret_error;
    }

    char filter[1024];
    snprintf(filter, sizeof(filter), "(&(objectClass=inetOrgPerson)(uid=%s))", conn->user);

    if (ldap_search_s(ldap->handle, ldap->base_dn, LDAP_SCOPE_SUBTREE, filter, NULL, 0, &search_result) != LDAP_SUCCESS) {
        goto cleanup;
    }

    int num_entries = ldap_count_entries(ldap->handle, search_result);
    if (num_entries != 1) {
        result = (num_entries == 0) ? ret_not_found : ret_error;
        goto cleanup;
    }

    LDAPMessage *entry = ldap_first_entry(ldap->handle, search_result);
    user_dn = ldap_get_dn(ldap->handle, entry);
    if (!user_dn) {
        goto cleanup;
    }

    if (ldap_bind_s(ldap->handle, user_dn, conn->password, LDAP_AUTH_SIMPLE) != LDAP_SUCCESS) {
        result = ret_error;
    } else {
        result = ret_ok;
    }

cleanup:
    if (user_dn) ldap_memfree(user_dn);
    if (search_result) ldap_msgfree(search_result);
    ldap_disconnect(ldap);
    return result;
}

ret_t validate_credentials_ldap(cherokee_validator_ldap_t *ldap, cherokee_connection_t *conn) {
    ret_t ret = ret_error;
    LDAPMessage *result = NULL;
    LDAPMessage *entry = NULL;
    char *dn = NULL;

    if (!ldap || !conn || !conn->user || !conn->password) {
        return ret_error;
    }

    const char *filter = "(&(objectClass=person)(uid=%s))";
    char search_filter[256];
    snprintf(search_filter, sizeof(search_filter), filter, conn->user);

    int msgid;
    if (ldap_search_ext_s(ldap->handle, ldap->base_dn, LDAP_SCOPE_SUBTREE, search_filter, NULL, 0, NULL, NULL, LDAP_NO_TIMEOUT, LDAP_NO_LIMIT, &result) != LDAP_SUCCESS) {
        return ret_error;
    }

    int count = ldap_count_entries(ldap->handle, result);
    if (count != 1) {
        ldap_msgfree(result);
        return (count == 0) ? ret_not_found : ret_error;
    }

    entry = ldap_first_entry(ldap->handle, result);
    if (!entry) {
        ldap_msgfree(result);
        return ret_error;
    }

    dn = ldap_get_dn(ldap->handle, entry);
    if (!dn) {
        ldap_msgfree(result);
        return ret_error;
    }

    if (ldap_bind_s(ldap->handle, dn, conn->password, LDAP_AUTH_SIMPLE) != LDAP_SUCCESS) {
        cherokee_free(dn);
        ldap_msgfree(result);
        return ret_error;
    }

    cherokee_free(dn);
    ldap_msgfree(result);

    if (ldap_unbind_ext_s(ldap->handle, NULL, NULL) != LDAP_SUCCESS) {
        return ret_error;
    }

    return ret_ok;
}

ret_t validate_credentials_ldap(cherokee_validator_ldap_t *ldap, cherokee_connection_t *conn) {
    ret_t ret = ret_error;
    LDAPMessage *res = NULL;
    char *search_filter = NULL;
    char *dn = NULL;

    if (!ldap || !conn || !conn->user || !conn->password) {
        return ret_error;
    }

    /* Build search filter */
    search_filter = cherokee_build_ldap_filter(conn->user);
    if (!search_filter) {
        return ret_error;
    }

    /* Perform LDAP search */
    if (ldap_search_s(ldap->ld, ldap->base_dn, LDAP_SCOPE_SUBTREE, search_filter, NULL, 0, &res) != LDAP_SUCCESS) {
        free(search_filter);
        return ret_error;
    }

    if (ldap_count_entries(ldap->ld, res) != 1) {
        ldap_msgfree(res);
        free(search_filter);
        return ret_not_found;
    }

    LDAPMessage *entry = ldap_first_entry(ldap->ld, res);
    dn = ldap_get_dn(ldap->ld, entry);
    if (!dn) {
        ldap_msgfree(res);
        free(search_filter);
        return ret_error;
    }

    /* Validate DN and password */
    if (ldap_bind_s(ldap->ld, dn, conn->password, LDAP_AUTH_SIMPLE) != LDAP_SUCCESS) {
        ret = ret_not_found;
    } else {
        ret = ret_ok;
    }

    ldap_msgfree(res);
    ldap_memfree(dn);
    free(search_filter);
    return ret;
}

ret_t validate_credentials_ldap(cherokee_validator_ldap_t *ldap, cherokee_connection_t *conn) {
    ret_t ret = ret_error;
    LDAPMessage *result = NULL;
    char *dn = NULL;
    char *filter;
    int msgid;
    struct timeval tv;
    int matched = 0;

    if (!ldap || !conn || !conn->user.name || !conn->user.password) {
        return ret_error;
    }

    filter = cherokee_buffer_new();
    if (!filter) {
        return ret_error;
    }

    cherokee_buffer_addf(filter, "(&(objectClass=inetOrgPerson)(uid=%s))", conn->user.name);

    if (LDAP_SUCCESS != ldap_search_ext_s(ldap->handle, ldap->base_dn, LDAP_SCOPE_SUBTREE, filter, NULL, 0, NULL, NULL, &tv, &msgid, &result)) {
        cherokee_buffer_free(filter);
        return ret_error;
    }

    if (!result) {
        cherokee_buffer_free(filter);
        return ret_not_found;
    }

    LDAPMessage *entry = ldap_first_entry(ldap->handle, result);
    if (!entry) {
        cherokee_buffer_free(filter);
        ldap_msgfree(result);
        return ret_not_found;
    }

    dn = ldap_get_dn(ldap->handle, entry);
    if (!dn) {
        cherokee_buffer_free(filter);
        ldap_msgfree(result);
        return ret_error;
    }

    if (LDAP_SUCCESS != ldap_bind_s(ldap->handle, dn, conn->user.password, LDAP_AUTH_SIMPLE)) {
        cherokee_buffer_free(filter);
        ldap_memfree(dn);
        ldap_msgfree(result);
        return ret_not_found;
    }

    ret = ret_ok;

    ldap_memfree(dn);
    ldap_msgfree(result);
    cherokee_buffer_free(filter);
    return ret;
}
